48:      * @param {string} input
49:      * @param {Object[]} args
50:      * @returns {json}
51:      */
52:     run(input, args) {
53:         const output = {},
54:             charsets = Object.keys(IO_FORMAT),
55:             mode = args[0];
56: 
57:         charsets.forEach(charset => {
58:             try {
59:                 if (mode === "Decode") {
60:                     output[charset] = cptable.utils.decode(IO_FORMAT[charset], input);
61:                 } else {
62:                     output[charset] = Utils.arrayBufferToStr(cptable.utils.encode(IO_FORMAT[charset], input));
63:                 }
64:             } catch (err) {
65:                 output[charset] = "Could not decode.";
66:             }
67:         });
68: 
69:         return output;
70:     }
